-- User-made groups in the overlay editor (SW-236).
--
-- A group is a named node in a tree: it can sit inside another group, and an
-- item points at the innermost group it belongs to. Groups are editor
-- structure only. The live overlay never reads them, so nothing here changes
-- what a viewer sees.
--
-- Ids are generated by the editor (crypto.randomUUID), not by the database, so
-- a save can write a new group and the items inside it without a temp-id remap.
--
-- Both references carry scene_id so a group can only hold items, and only sit
-- inside groups, of its own scene. Deleting a group drops the reference rather
-- than the rows: its items become ungrouped and its child groups move up to the
-- root, which is what the editor's save expects when it removes a stale group.
--
-- This is not the clips widget's nesting. clip_display_field children keep
-- pointing at their parent through config.parentClipItemId and never get a
-- group_id.

CREATE TABLE public.overlay_item_groups (
  id              uuid PRIMARY KEY,
  scene_id        uuid NOT NULL REFERENCES public.overlay_scenes (id) ON DELETE CASCADE,
  parent_group_id uuid,
  label           text NOT NULL DEFAULT 'Group' CHECK (char_length(label) BETWEEN 1 AND 100),
  created_at      timestamptz NOT NULL DEFAULT now(),
  -- Target of the scene-scoped references below.
  UNIQUE (id, scene_id),
  CHECK (parent_group_id IS NULL OR parent_group_id <> id),
  FOREIGN KEY (parent_group_id, scene_id)
    REFERENCES public.overlay_item_groups (id, scene_id)
    ON DELETE SET NULL (parent_group_id)
);

CREATE INDEX overlay_item_groups_scene_id_idx ON public.overlay_item_groups (scene_id);

ALTER TABLE public.overlay_items
  ADD COLUMN IF NOT EXISTS group_id uuid,
  ADD CONSTRAINT overlay_items_group_id_fkey
    FOREIGN KEY (group_id, scene_id)
    REFERENCES public.overlay_item_groups (id, scene_id)
    ON DELETE SET NULL (group_id);

CREATE INDEX overlay_items_group_id_idx ON public.overlay_items (group_id)
  WHERE group_id IS NOT NULL;

-- Same ownership rule as overlay_items: the scene's owner, and nobody else.
-- No public read; the overlay page doesn't need groups.
ALTER TABLE public.overlay_item_groups ENABLE ROW LEVEL SECURITY;

CREATE POLICY overlay_item_groups_owner_all ON public.overlay_item_groups
  FOR ALL
  USING (EXISTS (
    SELECT 1 FROM public.overlay_scenes
    WHERE overlay_scenes.id = overlay_item_groups.scene_id
      AND overlay_scenes.user_id = (SELECT auth.uid())
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.overlay_scenes
    WHERE overlay_scenes.id = overlay_item_groups.scene_id
      AND overlay_scenes.user_id = (SELECT auth.uid())
  ));
